mapper.select:
SELECT a.STATUS, a.COUNTER_ID, a.COUNTER_NAME, a.COUNTER_TYPE1, a.COUNTER_TYPE2, a.CREATE_USER, a.CREATE_TIME as createTime, a.UPDATE_USER, a.UPDATE_TIME as updateTime, a.SVR_DATA_SOURCES as dataSource, '' as uuid, FROM chb_mst_counter_party a
not EXISTS ( SELECT 1 from chb_mst_counter_party_errordata c where c.COUNTER_ID=a.COUNTER_ID and c.STATUS in('A','E') )
#{counterId,jdbcType=VARCHAR}
#{counterType2,jdbcType=VARCHAR}
#{status,jdbcType=VARCHAR}
union all SELECT 'A' as 数据状态, c.COUNTER_ID, c.COUNTER_NAME, c.COUNTER_TYPE1, c.COUNTER_TYPE2, c.CREATE_USER, c.CREATE_TIME as createTime, c.UPDATE_USER, c.UPDATE_TIME as updateTime, 'DB' as dataSource, c.DATAUUID as uuid, FROM chb_mst_counter_party_errordata c
c.STATUS in('A','E')
#{counterId,jdbcType=VARCHAR}
#{counterType2,jdbcType=VARCHAR}
and 1 = 2

mapper.update:
update chb_mst_counter_party set STATUS = 'E',SVR_DATA_SOURCES='02',
COUNTER_NAME= #{counterName,jdbcType=VARCHAR},COUNTER_TYPE2= #{counterType2,jdbcType=VARCHAR}
where
	COUNTER_ID = #{counterId,jdbcType=VARCHAR}

mapper.delete:
delete from chb_mst_counter_party_errordata a
where
COUNTER_ID = #{counterId,jdbcType=VARCHAR}

mapper.select:
	SELECT count(1) from (
SELECT 1 from REP_CASH_YIELD a
	where a.STATUS in('A','E')
	and not EXISTS (
	 SELECT 1 from 	REP_CASH_YIELD_ERRORDATA b
			WHERE b.PROD_ID=a.BUSI_ID
				and b.CASH_TYPE_2=a.CASH_TYPE2
			and b.START_DATE=a.START_DATE
			and b.STATUS in('A','E')
	) and

	a.BUSI_ID = #{item.busiId,jdbcType=VARCHAR}
	and a.START_DATE = #{item.startDate,jdbcType=DATE}
	and a.CASH_TYPE2 = #{item.cashType2,jdbcType=VARCHAR}


	union all
	SELECT 1 from rep_cash_yield_errordata c
	where c.STATUS in('A','E')
and

	c.PROD_ID = #{item.busiId,jdbcType=VARCHAR}
	and c.START_DATE = #{item.startDate,jdbcType=DATE}
	and c.CASH_TYPE_2 = #{item.cashType2,jdbcType=VARCHAR}


)tmp
